// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
        LogShim log = new LogShim();
        c.SetLogFile(address(log));
    }

    function testFuzz_property(uint256 amt, uint256 lockTime, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amt = bound(amt, 0, 1e30);
        lockTime = bound(lockTime, 0, 1e18);
        v2 = bound(v2, 0, type(uint256).max - 1);

        // Deposit activity through the public entry (exercises the nonReentrant_ modifier).
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(lockTime);

        // Rule: while uninitialized, SetMinSum always succeeds and records the new value.
        bool ok;
        try c.SetMinSum(v2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.MinSum() == v2);
    }
}

// Minimal shim so C's Put can log without reverting (a fuzzed EOA log would revert).
contract LogShim {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
